6	const readStdin = async (): Promise<string> => {
7	  const chunks: string[] = [];
8	  process.stdin.setEncoding("utf8");
9	  for await (const chunk of process.stdin) {
10	    chunks.push(chunk as string);
11	  }
12	  return chunks.join("");
13	};
